inline double muffin_weight(float tau1decayMode, float ptratio, float tau1Pt, float nsmalljets, float nbtags, float tau1Eta, float tau1Phi) {
    const float x[7] = {tau1decayMode, ptratio, tau1Pt, nsmalljets, nbtags, tau1Eta, tau1Phi};
  return MUFFIN_POSTER::eval(x, MUFFIN_POSTER::FEAT_nominal, MUFFIN_POSTER::THR_nominal, MUFFIN_POSTER::LEFT_nominal,
                  MUFFIN_POSTER::RIGHT_nominal, MUFFIN_POSTER::MISS_nominal, MUFFIN_POSTER::OFF_nominal,
                  MUFFIN_POSTER::NTREE_nominal, MUFFIN_POSTER::B0_nominal, MUFFIN_POSTER::NORM_nominal);
}

